function openTransaction(n){window.location.href="/cuentas/transaccion/"+n}function errorDialog(){swal({title:"ERROR",text:"No se pudo solicitar el adelanto. Inténtalo más tarde.",icon:"warning",buttons:{cancel:{text:"Cerrar",value:!1,visible:!0,className:"btn btn-primary",closeModal:!0}}}).then(n=>{swal.close()})}function successialog(){swal({title:"Procesando Adelanto",text:"El pedido de adelanto fue recibido y será analizado por nuestro departamento de riesgo. Te estaremos contactando a la brevedad.",icon:"success",buttons:{cancel:{text:"Cerrar",value:!1,visible:!0,className:"btn btn-primary",closeModal:!0}}}).then(n=>{swal.close()})}function checkPaymentInAdvanceAmount(){const n=parseInt($("[name='paymentInAdvanceAmount']").attr("min")),e=parseInt($("[name='paymentInAdvanceAmount']").attr("max"));let a=parseInt($("[name='paymentInAdvanceAmount']").val()),t=!0;if(n>a&&($("[name='paymentInAdvanceAmount']").val(n),t=!1),e<a&&($("[name='paymentInAdvanceAmount']").val(e),t=!1),!t){const a=document.createElement("div");a.innerHTML='\n                <h3 class="mb-3">Error en monto de anticipo</h3>\n                <p class="text-left"> \n                    El monto de anticipo solicitado se encuentra fuera del rango permitido:\n                </p> \n                <h4>\n                    Rando permitido de adelanto: <small class=\'mr-2\'>USD</small>'+n+" a <small class='mr-2'>USD</small>"+e+'\n                </h5>\n                <p class="text-left">\n                    Vuelve a intentarlo, eligiendo un monto dentro del rango anteriormente mencionado.\n                </p>\n            ',swal({content:a,icon:"warning",buttons:{cancel:{text:"Cerrar",value:!1,visible:!0,className:"btn btn-primary",closeModal:!0}}}).then(n=>{swal.close()})}return t}function requestPaymentInAdvance(){checkPaymentInAdvanceAmount()&&$.post("/api/accounts/request/advance",{lotId:parseInt($("[name='paymentInAdvanceLotId']").val()),amount:parseInt($("[name='paymentInAdvanceAmount']").val())},function(n){let e=!0,a=0,t=0;"error"in n&&!n.error&&n.paymentInAdvanceId&&(e=!1,a=n.paymentInAdvanceId,t=n.paymentsInAdvanceAmount),e?errorDialog():($("#paymentInAdvanceSection").removeClass("text-left"),$("#paymentInAdvanceSection").addClass("text-center"),$("#paymentInAdvanceSection").addClass("bg-warning"),$("#paymentInAdvanceSection").html('\n                            <p class="m-0 p-2 w-100">\n                                Adelanto #'+a+" por</br>\n                                <b>USD "+t+"</b></br>\n                                en proceso\n                            </p>\n                        "),successialog())})}